window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fff9982d2eb42b3f"]={"versions": [{"id": "FIG-fff9982d2eb42b3f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Interaktionsdiagramm für die AUTOSAR Classic Platform. Das Diagramm illustriert das Routing und die Zuordnung von I-PDU-IDs im Kommunikationsstapel zwischen COM, PDU Router (PduR) und CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>COM</strong>: Oberes Kommunikationsmodul (Upper Layer BSW).\n</li><li><strong>PduR</strong>: Zentraler PDU-Router zur Weiterleitung und ID-Umsetzung.\n</li><li><strong>CanIf</strong>: Unteres Schnittstellenmodul für den CAN-Bus (Lower Layer BSW).\n</li><li><strong>Schnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>PduR Transmit(11)</code>: Aufruf von COM an PduR mit der I-PDU-ID 11.\n</li><li><code>CanIf Transmit(22)</code>: Aufruf von PduR an CanIf mit der umgesetzten I-PDU-ID 22.\n</li><li><code>PduR CanIfTxConfirmation(42)</code>: Bestätigungsaufruf von CanIf an PduR mit der I-PDU-ID 42.\n</li><li><code>Com TxConfirmation(32)</code>: Bestätigungsaufruf von PduR an COM mit der I-PDU-ID 32.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>COM initiiert das Senden einer I-PDU durch Aufruf von <code>PduR Transmit(11)</code>.\n</li><li>PduR übersetzt die konfigurierte I-PDU-ID (11) für die Ziel-Schnittstelle und ruft <code>CanIf Transmit(22)</code> auf.\n</li><li>Nach erfolgreicher Übertragung meldet CanIf den Vollzug über <code>PduR CanIfTxConfirmation(42)</code> an PduR zurück.\n</li><li>PduR leitet die Sendebestätigung an das Ursprungsmodul weiter und ruft <code>Com TxConfirmation(32)</code> auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht beispielhaft, dass I-PDU-IDs modul- und schnittstellenspezifisch konfiguriert sind. Jedes beteiligte BSW-Modul (COM, PduR, CanIf) nutzt für dieselbe logische PDU im Sende- und Bestätigungspfad eigene numerische Bezeichner, die bei der Konfiguration in der Routingtabelle des PduR aufeinander abgebildet werden müssen. Die Funktionsnamen sind im Diagramm mit Leerzeichen statt Unterstrichen dargestellt.</p>"}, {"id": "FIG-dad43eac9c763cca", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Interaktionsdiagramm für die AUTOSAR Classic Platform. Das Diagramm illustriert das Routing und die Zuordnung von I-PDU-IDs im Kommunikationsstapel zwischen COM, PDU Router (PduR) und CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>COM</strong>: Oberes Kommunikationsmodul (Upper Layer BSW).\n</li><li><strong>PduR</strong>: Zentraler PDU-Router zur Weiterleitung und ID-Umsetzung.\n</li><li><strong>CanIf</strong>: Unteres Schnittstellenmodul für den CAN-Bus (Lower Layer BSW).\n</li><li><strong>Schnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>PduR_Transmit(11)</code>: Aufruf von COM an PduR mit der I-PDU-ID 11.\n</li><li><code>CanIf_Transmit(22)</code>: Aufruf von PduR an CanIf mit der umgesetzten I-PDU-ID 22.\n</li><li><code>PduR_CanIfTxConfirmation(42)</code>: Bestätigungsaufruf von CanIf an PduR mit der I-PDU-ID 42.\n</li><li><code>Com_TxConfirmation(32)</code>: Bestätigungsaufruf von PduR an COM mit der I-PDU-ID 32.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>COM initiiert das Senden einer I-PDU durch Aufruf von <code>PduR_Transmit(11)</code>.\n</li><li>PduR übersetzt die konfigurierte I-PDU-ID (11) für die Ziel-Schnittstelle und ruft <code>CanIf_Transmit(22)</code> auf.\n</li><li>Nach erfolgreicher Übertragung meldet CanIf den Vollzug über <code>PduR_CanIfTxConfirmation(42)</code> an PduR zurück.\n</li><li>PduR leitet die Sendebestätigung an das Ursprungsmodul weiter und ruft <code>Com_TxConfirmation(32)</code> auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht beispielhaft, dass I-PDU-IDs modul- und schnittstellenspezifisch konfiguriert sind. Jedes beteiligte BSW-Modul (COM, PduR, CanIf) nutzt für dieselbe logische PDU im Sende- und Bestätigungspfad eigene numerische Bezeichner, die bei der Konfiguration in der Routingtabelle des PduR aufeinander abgebildet werden müssen. Die Funktionsbezeichner entsprechen der AUTOSAR-C-API-Nomenklatur mit Unterstrichen.</p>"}, {"id": "FIG-bbf50d5500cc2b92", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Interaktionsdiagramm für die AUTOSAR Classic Platform. Das Diagramm illustriert das Routing und die Zuordnung von I-PDU-IDs im Kommunikationsstapel zwischen COM, PDU Router (PduR) und CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>COM</strong>: Oberes Kommunikationsmodul (Upper Layer BSW).\n</li><li><strong>PduR</strong>: Zentraler PDU-Router zur Weiterleitung und ID-Umsetzung.\n</li><li><strong>CanIf</strong>: Unteres Schnittstellenmodul für den CAN-Bus (Lower Layer BSW).\n</li><li><strong>Schnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>PduR_ComTransmit(11)</code>: Aufruf von COM an PduR mit der I-PDU-ID 11.\n</li><li><code>CanIf_Transmit(22)</code>: Aufruf von PduR an CanIf mit der umgesetzten I-PDU-ID 22.\n</li><li><code>PduR_CanIfTxConfirmation(42)</code>: Bestätigungsaufruf von CanIf an PduR mit der I-PDU-ID 42.\n</li><li><code>Com_TxConfirmation(32)</code>: Bestätigungsaufruf von PduR an COM mit der I-PDU-ID 32.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>COM initiiert das Senden einer I-PDU durch Aufruf von <code>PduR_ComTransmit(11)</code>.\n</li><li>PduR übersetzt die konfigurierte I-PDU-ID (11) für die Ziel-Schnittstelle und ruft <code>CanIf_Transmit(22)</code> auf.\n</li><li>Nach erfolgreicher Übertragung meldet CanIf den Vollzug über <code>PduR_CanIfTxConfirmation(42)</code> an PduR zurück.\n</li><li>PduR leitet die Sendebestätigung an das Ursprungsmodul weiter und ruft <code>Com_TxConfirmation(32)</code> auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht beispielhaft, dass I-PDU-IDs modul- und schnittstellenspezifisch konfiguriert sind. Jedes beteiligte BSW-Modul (COM, PduR, CanIf) nutzt für dieselbe logische PDU im Sende- und Bestätigungspfad eigene numerische Bezeichner, die bei der Konfiguration in der Routingtabelle des PduR aufeinander abgebildet werden müssen. Für den Sendeaufruf von COM an den PduR wird die oberschichtspezifische API <code>PduR_&lt;User:COM&gt;Transmit</code> verwendet.</p>"}], "trans": [{"from": "FIG-fff9982d2eb42b3f", "to": "FIG-dad43eac9c763cca", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Formatierung der Funktionsaufrufe: Leerzeichen zwischen Modulpräfix und Funktionsname durch Unterstriche (<code>_</code>) ersetzt (<code>PduR Transmit(11)</code> -&gt; <code>PduR_Transmit(11)</code>, <code>Com TxConfirmation(32)</code> -&gt; <code>Com_TxConfirmation(32)</code>, <code>CanIf Transmit(22)</code> -&gt; <code>CanIf_Transmit(22)</code>, <code>PduR CanIfTxConfirmation(42)</code> -&gt; <code>PduR_CanIfTxConfirmation(42)</code>).\n</li></ul>"}, {"from": "FIG-dad43eac9c763cca", "to": "FIG-bbf50d5500cc2b92", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Schnittstellenfunktion von COM zu PduR: Funktionsaufruf <code>PduR_Transmit(11)</code> umbenannt in die oberschichtenspezifische API <code>PduR_ComTransmit(11)</code>.\n</li></ul>"}]};
